# 🟢 低风险：只读/信息收集，通常无副作用
# 创建弹性节点池（Spot + 按量混合）
cat > elastic-nodepool.json << 'EOF'
{
  "nodepool_info": {
    "name": "elastic-spot-pool"
  },
  "scaling_group": {
    "vswitch_ids": ["<vsw-id-az-a>", "<vsw-id-az-b>"],
    "instance_types": [
      "ecs.g6.xlarge",
      "ecs.g6a.xlarge",
      "ecs.g7.xlarge"
    ],
    "system_disk_category": "cloud_essd",
    "system_disk_size": 120,
    "spot_strategy": "SpotAsPriceGo",
    "multi_az_policy": "BALANCE",
    "key_pair": "<your-key-pair>"
  },
  "kubernetes_config": {
    "labels": [
      {"key": "workload", "value": "elastic"},
      {"key": "spot", "value": "true"}
    ],
    "taints": [
      {"key": "spot", "value": "true", "effect": "NoSchedule"}
    ]
  },
  "management": {
    "auto_repair": true
  },
  "auto_scaling": {
    "enable": true,
    "min_instances": 0,
    "max_instances": 20
  },
  "count": 0
}
EOF

aliyun cs POST /clusters/<cluster_id>/nodepools \
  --body "$(cat elastic-nodepool.json)"
